SELECT p.id,p.name,p.category_path FROM products p WHERE p.visible=1 AND (LOWER(p.name) REGEXP 'турнікет|джгут|гемостат|бандаж|аптечка|ifak' AND LOWER(p.name) NOT REGEXP 'тренув|тренир|навчал|учб|маркер|сумк|підсум|чохол|порожн|без наповнення') AND EXISTS(SELECT 1 FROM photos ph WHERE ph.product_id=p.id) AND EXISTS(SELECT 1 FROM variants v WHERE v.product_id=p.id AND v.price>0 AND v.availability IN ('in','order')) ORDER BY FIELD(p.availability,'in','order','out'),p.updated_at DESC,p.id;
